const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=(v='')=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const fmtDate=v=>v?new Date(v).toLocaleDateString('en-AU',{day:'2-digit',month:'short',year:'numeric'}):'—';
const fmtTime=v=>v?new Date(v).toLocaleString('en-AU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'—';
const pct=(n,d)=>d?Math.round(Number(n||0)*100/Number(d)):0;
const app=$('#app');
const state={user:null,view:'dashboard',projectId:'',projects:[],systems:[],equipment:[],templates:[],inspections:[],defects:[],points:[],turnover:[],witness:[],dashboard:{},users:[],actions:[],myWork:{actions:[],defects:[],inspections:[],witness:[]},matrix:[],files:[],query:'',filters:{},intelligence:null,copilot:null,documents:[],signoffs:[],notifications:[],drawings:[],v7ready:false,v8ready:false,portfolio:[],observations:[],milestones:[],equipmentReadiness:[],syncConflicts:[],offlinePackAt:null,smartForm:null};

const API_CACHE='qx-api-cache:'; const QUEUE_KEY='qx-offline-queue-v2';
function getQueue(){try{return JSON.parse(localStorage.getItem(QUEUE_KEY)||'[]')}catch{return[]}}
function setQueue(q){localStorage.setItem(QUEUE_KEY,JSON.stringify(q))}
async function api(path,options={}){const method=(options.method||'GET').toUpperCase();const headers={...(options.body&&!(options.body instanceof Blob)?{'content-type':'application/json'}:{}),...(options.headers||{})};let r;try{r=await fetch(path,{credentials:'same-origin',headers,...options})}catch(err){if(method==='GET'){try{const hit=JSON.parse(localStorage.getItem(API_CACHE+path)||'null');if(hit?.data)return hit.data}catch{}throw err}const queueable=['POST','PATCH','DELETE'].includes(method)&&typeof options.body==='string'&&!path.startsWith('/api/auth/')&&!path.startsWith('/api/setup/');if(queueable&&!navigator.onLine){const q=getQueue();q.push({id:crypto.randomUUID(),path,method,body:options.body,headers,queued_at:new Date().toISOString()});setQueue(q);updateQueueBadge();return {queued:true,offline:true}}throw err}let d=null;try{d=await r.json()}catch{}if(!r.ok)throw new Error(d?.error||`Request failed (${r.status})`);if(method==='GET'&&d)localStorage.setItem(API_CACHE+path,JSON.stringify({at:Date.now(),data:d}));return d}
async function flushQueue(){if(!navigator.onLine)return;const q=getQueue();if(!q.length)return;const remaining=[];for(const item of q){try{const r=await fetch(item.path,{method:item.method,body:item.body,credentials:'same-origin',headers:item.headers});if(!r.ok)remaining.push(item)}catch{remaining.push(item)}}setQueue(remaining);updateQueueBadge();if(q.length!==remaining.length){toast(`${q.length-remaining.length} offline update${q.length-remaining.length===1?'':'s'} synchronised`);try{await loadAll();render()}catch{}}}
function updateQueueBadge(){const el=$('#networkState');if(!el)return;const n=getQueue().length;if(!navigator.onLine){el.textContent=`● OFFLINE${n?` • ${n} queued`:''}`;el.classList.add('off')}else{el.textContent=n?`● LIVE • ${n} syncing`:'● LIVE';el.classList.remove('off')}}
function toast(msg){document.body.insertAdjacentHTML('beforeend',`<div class="toast">${esc(msg)}</div>`);setTimeout(()=>$('.toast')?.remove(),2200)}
function pill(v){const s=String(v||'not_started').replaceAll('_',' ');return `<span class="pill ${esc(String(v||''))}">${esc(s)}</span>`}
function progress(v){const n=Math.max(0,Math.min(100,Number(v||0)));return `<div class="readiness"><div class="progress"><i style="width:${n}%"></i></div><b>${n}%</b></div>`}
function currentProject(){return state.projects.find(p=>p.id===state.projectId)||null}
function projectName(id){const p=state.projects.find(x=>x.id===id);return p?`${p.code} — ${p.name}`:'—'}
function filtered(rows){if(!state.projectId)return rows;return rows.filter(x=>x.project_id===state.projectId)}

function navBtn(id,icon,label){return `<button class="navbtn ${state.view===id?'active':''}" data-view="${id}"><span class="navicon">${icon}</span>${label}</button>`}
function shell(content){const u=state.user||{};return `<div class="layout"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brandmark">QX</div><div><b>Elliot Qx</b><small>Commissioning OS V8.3</small></div></div><div class="navlabel">Command</div>${navBtn('portfolio','◫','Portfolio')}${navBtn('dashboard','◈','Command Centre')}${navBtn('fieldhub','⚡','Field Hub')}${navBtn('mywork','☑','My Work')}${navBtn('matrix','▦','Completion Matrix')}${navBtn('intelligence','◆','Qx Intelligence')}${navBtn('notifications','◉','Alerts & Escalations')}<div class="navlabel">Project</div>${navBtn('projects','▧','Projects')}${navBtn('systems','⌘','Systems & Readiness')}${navBtn('equipment','◇','Asset Passports')}${navBtn('builder','✦','Project Builder')}${navBtn('drawings','⌗','Drawings & Markups')}${navBtn('planner','◷','Commissioning Plan')}<div class="navlabel">Field Execution</div>${navBtn('inspections','✓','QA & Commissioning')}${navBtn('points','↯','BMS I/O Checkout')}${navBtn('defects','!','Defects / Punch')}${navBtn('evidence','◫','Evidence Hub')}${navBtn('observations','●','Field Observations')}<div class="navlabel">Completion</div>${navBtn('witness','◎','Witness & Hold Points')}${navBtn('turnover','▣','Turnover Packages')}${navBtn('reports','▤','Reports & Handover')}${navBtn('closeout','✦','Closeout Studio')}${navBtn('templates','≡','Template Library')}${navBtn('smarttemplates','✦','Smart Template Builder')}${u.role==='admin'?navBtn('admin','⚙','Admin'):''}<div class="sidefoot"><div class="userline"><div class="avatar">${esc((u.name||'U')[0])}</div><div><b>${esc(u.name||'User')}</b><small>${esc(u.role||'')}</small></div></div><button class="navbtn" id="logout" style="margin-top:8px"><span class="navicon">↪</span>Sign out</button></div></aside><main class="main"><header class="topbar"><button class="btn btn-small mobile-menu" id="menuBtn">☰</button><select class="project-picker" id="projectPicker"><option value="">All projects / portfolio</option>${state.projects.map(p=>`<option value="${p.id}" ${p.id===state.projectId?'selected':''}>${esc(p.code)} — ${esc(p.name)}</option>`).join('')}</select><button class="btn btn-small" id="scanAsset">▣ Scan asset</button><span class="online ${navigator.onLine?'':'off'}" id="networkState">${navigator.onLine?'● LIVE':'● OFFLINE'}</span></header><section class="content">${content}</section></main></div>`}
function hero(title,sub,actions=''){return `<div class="hero"><div><div class="eyebrow">${esc(currentProject()?.code||'ELLIOT CONTROLS')}</div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="actions">${actions}</div></div>`}
function card(label,value,sub='',tone=''){return `<div class="card kpi"><div class="label">${label}</div><div class="metric ${tone}">${value}</div><div class="sub">${sub}</div></div>`}

function renderLogin(initialized=true){app.innerHTML=`<div class="auth"><div class="auth-card"><div class="brandmark">QX</div><h1>Elliot Qx</h1><p>${initialized?'QA, commissioning, systems completion and turnover — one source of truth from install to handover.':'Create the first secure administrator account.'}</p><form id="authForm">${!initialized?`<div class="field"><label>Your name</label><input name="name" required></div>`:''}<div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Password</label><input name="password" type="password" minlength="12" required></div><button class="btn btn-primary" style="width:100%">${initialized?'Sign in':'Create administrator'}</button></form><div id="authError"></div></div></div>`;$('#authForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{if(initialized){const r=await api('/api/auth/login',{method:'POST',body:JSON.stringify(data)});state.user=r.user;await loadAll();render()}else{const r=await api('/api/setup/bootstrap',{method:'POST',body:JSON.stringify(data)});state.user=r.user;await loadAll();render()}}catch(err){$('#authError').innerHTML=`<div class="error" style="margin-top:12px">${esc(err.message)}</div>`}}}

async function loadAll(){const q=state.projectId?`?project_id=${encodeURIComponent(state.projectId)}`:'';const [p,t,d,s,e,i,df,pts,top,w,u,a,mw,fs]=await Promise.all([api('/api/projects'),api('/api/templates'),api(`/api/dashboard${q}`),api(`/api/systems${q}`),api(`/api/equipment${q}`),api(`/api/inspections${q}`),api(`/api/defects${q}`),api(`/api/bms-points${q}`),api(`/api/turnover${q}`),api(`/api/witness${q}`),api('/api/users'),api(`/api/actions${q}`),api(`/api/my-work${q}`),state.projectId?api(`/api/files?project_id=${encodeURIComponent(state.projectId)}`):Promise.resolve({files:[]})]);state.projects=p.projects;state.templates=t.templates;state.dashboard=d;state.systems=s.systems;state.equipment=e.equipment;state.inspections=i.inspections;state.defects=df.defects;state.points=pts.points;state.turnover=top.packages;state.witness=w.witness;state.users=u.users;state.actions=a.actions||[];state.myWork=mw||{actions:[],defects:[],inspections:[],witness:[]};state.files=fs.files||[];state.matrix=[];if(state.projectId){try{state.matrix=(await api(`/api/completion-matrix?project_id=${encodeURIComponent(state.projectId)}`)).systems||[]}catch{state.matrix=[]}}}
async function boot(){try{setQueue(getQueue().filter(x=>!String(x.path||'').startsWith('/api/auth/')&&!String(x.path||'').startsWith('/api/setup/')));if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});const st=await api('/api/setup/status');if(!st.initialized)return renderLogin(false);const me=await api('/api/me');state.user=me.user;await loadAll();render();const asset=new URLSearchParams(location.search).get('asset');if(asset)setTimeout(()=>openAssetPassport(asset),50)}catch(e){renderLogin(true)}}

function dashboardView(){const d=state.dashboard,eq=d.equipment||{},df=d.defects||{},ins=d.inspections||{},pts=d.points||{},top=d.turnover||{},wit=d.witness||{};const eqp=pct(eq.complete,eq.total),pointp=pct(pts.passed,pts.total),turn=Math.round(Number(top.avg_readiness||0));const p=currentProject();return `${hero(p?'Project Command Centre':'Portfolio Command Centre','Live readiness, blockers, field execution and handover position',`<button class="btn btn-primary" id="quickTest">+ Start field test</button><button class="btn" id="quickDefect">+ Defect</button>`)}<div class="banner"><div style="font-size:22px">⚡</div><div><strong>Commissioning Readiness Engine</strong><p>Qx measures actual readiness from equipment, test completion, BMS I/O, Category A punch items, witness points and turnover evidence — not just checklist percentages.</p></div></div><div class="cards">${card('Equipment complete',`${eqp}%`,`${eq.complete||0} / ${eq.total||0} assets`,'green')}${card('BMS I/O proven',`${pointp}%`,`${pts.failed||0} failed points`,pts.failed?'red':'blue')}${card('Open punch',df.open||0,`${df.cat_a||0} Category A`,df.cat_a?'red':'amber')}${card('Witness holds',ins.witness||wit.requested||0,'Awaiting witness / approval','amber')}${card('Turnover readiness',`${turn}%`,`${top.ready||0} packages ready`,turn>85?'green':'blue')}${card('Live projects',d.projects?.active||0,`${d.projects?.total||0} total`,'blue')}</div><div class="grid2"><div><div class="section-head"><h3>${p?'System readiness':'Project readiness'}</h3><span>What is gating completion</span></div>${p?systemReadinessTable():projectTable(state.projects.slice(0,12))}</div><div><div class="section-head"><h3>Recent field activity</h3><span>Audit trail</span></div><div class="card activity">${(d.recent||[]).slice(0,10).map(a=>`<div class="activity-item"><b>${esc(a.user_name||'System')}</b> ${esc(a.action.replaceAll('_',' '))} ${esc(a.entity_type)}<small>${fmtTime(a.created_at)}</small></div>`).join('')||'<div class="empty">No activity yet</div>'}</div></div></div>`}
function projectTable(rows){if(!rows.length)return '<div class="card empty">No projects yet.</div>';return `<div class="table-wrap"><table><thead><tr><th>Project</th><th>Status</th><th>Systems</th><th>Equipment</th><th>Cat A</th><th>Open punch</th><th>Turnover</th></tr></thead><tbody>${rows.map(p=>`<tr><td><strong>${esc(p.code)}</strong><br><span class="muted">${esc(p.name)}</span></td><td>${pill(p.status)}</td><td>${p.system_count||0}</td><td>${p.equipment_count||0}</td><td>${p.cat_a||0}</td><td>${p.open_defects||0}</td><td>${progress(p.turnover_readiness||0)}</td></tr>`).join('')}</tbody></table></div>`}
function systemReadinessTable(){if(!state.systems.length)return '<div class="card empty">Create systems to start systemised completion tracking.</div>';return `<div class="table-wrap"><table><thead><tr><th>System</th><th>Discipline</th><th>Status</th><th>Equipment</th><th>Open punch</th><th>Target</th></tr></thead><tbody>${state.systems.map(s=>`<tr><td><strong>${esc(s.code)}</strong><br><span class="muted">${esc(s.name)}</span></td><td>${esc(s.discipline)}</td><td>${pill(s.status)}</td><td>${s.equipment_count||0}</td><td>${s.open_defects||0}</td><td>${fmtDate(s.target_date)}</td></tr>`).join('')}</tbody></table></div>`}

async function refreshIntelligence(){if(!state.projectId)return;try{state.intelligence=await api(`/api/readiness?project_id=${encodeURIComponent(state.projectId)}&snapshot=1`);render()}catch(e){toast(e.message)}}
function intelligenceView(){if(!state.projectId)return `${hero('Qx Intelligence','Select a project to calculate real commissioning readiness')}<div class="card empty">Choose a project from the top bar. Qx will calculate blockers across QA, BMS I/O, punch, witness and turnover.</div>`;const r=state.intelligence; if(!r){setTimeout(refreshIntelligence,0);return `${hero('Qx Intelligence','Calculating project readiness and completion blockers')}<div class="card empty">Analysing live project data…</div>`}return `${hero('Qx Intelligence','The shortest path from today to energisation, witness and handover','<button class="btn btn-primary" id="refreshIntel">Recalculate readiness</button>')}<div class="intel-grid"><div class="card"><div class="section-head"><h3>Readiness score</h3><span>${esc(r.grade)}</span></div><div class="readiness-ring" style="--p:${r.score}"><strong>${r.score}%</strong></div><p class="muted" style="text-align:center;margin-top:14px">Weighted from live QA, Category A punch, BMS I/O, witness, turnover and asset completion.</p></div><div class="card"><div class="section-head"><h3>Completion blockers</h3><span>${r.blockers.length} active</span></div>${r.blockers.length?r.blockers.map(b=>`<div class="blocker"><span class="sev ${esc(b.severity)}"></span><div><b>${esc(b.label)}</b><small>${esc(b.code.replaceAll('_',' '))}</small></div></div>`).join(''):'<div class="empty">No blocking conditions detected. Validate required evidence and authorised sign-offs before handover.</div>'}</div></div><div class="section-head"><h3>Why Qx wins for Elliot</h3><span>Built around field delivery</span></div><div class="cards"><div class="switch-reason"><b>One completion graph</b><span class="muted">Equipment, QA, I/O, punch, witness and turnover use the same live project structure.</span></div><div class="switch-reason"><b>BMS-native</b><span class="muted">Bulk point lists and four-stage I/O proof are first-class workflows, not generic forms.</span></div><div class="switch-reason"><b>Automatic blockers</b><span class="muted">PMs see why a system cannot be handed over instead of interpreting dozens of reports.</span></div><div class="switch-reason"><b>Evidence at the asset</b><span class="muted">Photos, tests, defects and sign-off remain tied to the equipment and system.</span></div></div>`}

function projectsView(){return `${hero('Projects','Portfolio, commissioning ownership and completion dates','<button class="btn btn-primary" id="addProject">+ New project</button>')}${projectTable(state.projects)}`}
function systemsView(){return `${hero('Systems & Readiness','Systemise the job exactly how it will be commissioned and handed over','<button class="btn btn-primary" id="addSystem">+ Add system</button><button class="btn" id="addTurnover">+ Turnover package</button>')}${systemReadinessTable()}`}
function equipmentView(){const rows=state.equipment;return `${hero('Asset Passports','Every asset linked to QA, tests, punch, I/O, evidence and sign-off','<button class="btn btn-primary" id="addEquipment">+ Add equipment</button><button class="btn" id="importEquipment">⇧ Import CSV</button>')}<div class="toolbar"><input class="search" id="searchBox" placeholder="Search tag, equipment, system, location…" value="${esc(state.query)}"><select class="mini-select" id="eqStatus"><option value="">All statuses</option><option>not_started</option><option>qa</option><option>commissioning</option><option>witness</option><option>blocked</option><option>complete</option></select></div>${equipmentTable(rows)}`}
function equipmentTable(rows){const q=state.query.toLowerCase(),st=state.filters.eqStatus||'';const list=rows.filter(e=>(!q||[e.tag,e.name,e.system,e.subsystem,e.building,e.level,e.area].join(' ').toLowerCase().includes(q))&&(!st||e.status===st));if(!list.length)return '<div class="card empty">No matching equipment.</div>';return `<div class="table-wrap"><table><thead><tr><th>Tag</th><th>Equipment</th><th>System</th><th>Location</th><th>Status</th><th>Approved tests</th><th>Punch</th><th>QR</th></tr></thead><tbody>${list.map(e=>`<tr><td><strong>${esc(e.tag)}</strong></td><td>${esc(e.name)}<br><span class="muted">${esc([e.manufacturer,e.model].filter(Boolean).join(' ')||e.equipment_type||'')}</span></td><td>${esc(e.system||'—')}<br><span class="muted">${esc(e.subsystem||'')}</span></td><td>${esc([e.building,e.level,e.area].filter(Boolean).join(' / ')||'—')}</td><td>${pill(e.status)}</td><td>${e.approved_tests||0}</td><td>${e.open_defects||0}</td><td><button class="btn btn-small" data-passport="${e.id}">Open</button></td></tr>`).join('')}</tbody></table></div>`}

function inspectionsView(){return `${hero('QA & Commissioning','Installation QA, ITPs, PFCs, FPTs and integrated testing','<button class="btn btn-primary" id="addInspection">+ Start test</button>')}<div class="toolbar"><input class="search" id="searchBox" placeholder="Search tests, asset tags, templates…" value="${esc(state.query)}"></div>${inspectionTable()}`}
function inspectionTable(){const q=state.query.toLowerCase(),list=state.inspections.filter(i=>!q||[i.title,i.equipment_tag,i.template_name,i.discipline].join(' ').toLowerCase().includes(q));if(!list.length)return '<div class="card empty">No QA or commissioning tests yet.</div>';return `<div class="table-wrap"><table><thead><tr><th>Test / Inspection</th><th>Asset</th><th>Stage</th><th>Progress</th><th>Fails</th><th>Status</th><th>Updated</th></tr></thead><tbody>${list.map(i=>`<tr data-inspection="${i.id}" style="cursor:pointer"><td><strong>${esc(i.title)}</strong><br><span class="muted">${esc(i.template_name)}</span></td><td>${esc(i.equipment_tag||'Project / system')}</td><td>${pill(i.stage)}</td><td>${progress(pct(i.answered,i.total_lines))}</td><td>${i.fails||0}</td><td>${pill(i.status)}</td><td>${fmtTime(i.updated_at)}</td></tr>`).join('')}</tbody></table></div>`}

function pointsView(){const points=state.points,q=state.query.toLowerCase(),list=points.filter(p=>!q||[p.controller,p.point_name,p.point_type,p.equipment_tag,p.io_address,p.cable_number].join(' ').toLowerCase().includes(q));const pass=list.filter(p=>p.overall_status==='pass').length,fail=list.filter(p=>p.overall_status==='fail').length;return `${hero('BMS I/O Checkout','Bulk point-to-point verification built for controls contractors','<button class="btn btn-primary" id="importPoints">⇧ Import CSV</button>')}<div class="cards" style="grid-template-columns:repeat(4,1fr)">${card('Points',list.length,'Current register','blue')}${card('Proven',pass,`${pct(pass,list.length)}% complete`,'green')}${card('Failed',fail,'Requires rectification',fail?'red':'')}${card('Untested',Math.max(0,list.length-pass-fail),'Field workload','amber')}</div><div class="toolbar"><input class="search" id="searchBox" placeholder="Search controller, point, address, cable…" value="${esc(state.query)}"></div>${list.length?`<div class="table-wrap"><table><thead><tr><th>Controller / Point</th><th>Type</th><th>Asset</th><th>Address</th><th>Field</th><th>Controller</th><th>Graphics</th><th>Alarm</th><th>Overall</th></tr></thead><tbody>${list.slice(0,1000).map(p=>`<tr data-point="${p.id}" style="cursor:pointer"><td><span class="muted">${esc(p.controller||'')}</span><br><strong>${esc(p.point_name)}</strong></td><td>${pill(p.point_type)}</td><td>${esc(p.equipment_tag||'—')}</td><td>${esc(p.io_address||'—')}</td><td>${pill(p.field_status)}</td><td>${pill(p.controller_status)}</td><td>${pill(p.graphics_status)}</td><td>${pill(p.alarm_status)}</td><td>${pill(p.overall_status)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="card empty">No BMS points yet. Import a CSV from your points list or I/O schedule.</div>'}`}

function defectsView(){const q=state.query.toLowerCase(),list=state.defects.filter(d=>!q||[d.title,d.description,d.equipment_tag,d.discipline,d.assigned_name].join(' ').toLowerCase().includes(q));const a=list.filter(d=>d.category==='A'&&!['closed','verified'].includes(d.status)).length;return `${hero('Defects & Punch','A/B/C completion punch with rectification evidence and verification','<button class="btn btn-primary" id="addDefect">+ Raise defect</button>')}<div class="cards" style="grid-template-columns:repeat(4,1fr)">${card('Category A',a,'Blocks energisation / turnover',a?'red':'green')}${card('Open',list.filter(d=>!['closed','verified'].includes(d.status)).length,'All active punch','amber')}${card('Rectified',list.filter(d=>d.status==='rectified').length,'Awaiting verification','blue')}${card('Closed',list.filter(d=>['closed','verified'].includes(d.status)).length,'Verified evidence','green')}</div><div class="toolbar"><input class="search" id="searchBox" placeholder="Search defect, asset, owner…" value="${esc(state.query)}"></div>${list.length?`<div class="table-wrap"><table><thead><tr><th>Cat</th><th>Defect</th><th>Asset</th><th>Discipline</th><th>Severity</th><th>Status</th><th>Owner</th><th>Due</th></tr></thead><tbody>${list.map(d=>`<tr data-defect="${d.id}" style="cursor:pointer"><td>${pill(d.category?.toLowerCase())}</td><td><strong>${esc(d.title)}</strong><br><span class="muted">${esc(d.description||'')}</span></td><td>${esc(d.equipment_tag||'—')}</td><td>${esc(d.discipline)}</td><td>${pill(d.severity)}</td><td>${pill(d.status)}</td><td>${esc(d.assigned_name||'Unassigned')}</td><td>${fmtDate(d.due_date)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="card empty">No defects.</div>'}`}

function witnessView(){return `${hero('Witness & Hold Points','Control client/consultant witness requests and approval gates','<button class="btn btn-primary" id="addWitness">+ Request witness</button>')}${state.witness.length?`<div class="table-wrap"><table><thead><tr><th>Requested</th><th>System</th><th>Test / Hold Point</th><th>Witness party</th><th>Status</th><th>Outcome</th></tr></thead><tbody>${state.witness.map(w=>`<tr><td><strong>${fmtDate(w.requested_for)}</strong></td><td>${esc(w.system_code||'—')}</td><td>${esc(w.inspection_title||'System witness')}</td><td>${esc(w.witness_party||'Client / consultant')}</td><td>${pill(w.status)}</td><td>${esc(w.outcome||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="card empty">No witness requests yet.</div>'}`}

function turnoverView(){const avg=state.turnover.length?Math.round(state.turnover.reduce((a,b)=>a+Number(b.readiness_percent||0),0)/state.turnover.length):0;return `${hero('Turnover Packages','Automatic closeout dossier readiness by system','<button class="btn btn-primary" id="addTurnover">+ New package</button>')}<div class="banner"><div style="font-size:22px">▣</div><div><strong>Handover without the end-of-job scramble</strong><p>Each package tracks as-builts, QA records, electrical tests, BMS I/O, functional tests, witness records, punch closure, O&M, backups and training evidence.</p></div></div><div class="cards" style="grid-template-columns:repeat(3,1fr)">${card('Portfolio readiness',`${avg}%`,'Across current packages',avg>85?'green':'blue')}${card('Ready packages',state.turnover.filter(x=>['ready','approved'].includes(x.status)).length,'Ready for acceptance','green')}${card('Incomplete',state.turnover.filter(x=>!['ready','approved'].includes(x.status)).length,'Outstanding dossier items','amber')}</div>${state.turnover.length?`<div class="grid3">${state.turnover.map(t=>`<div class="card" data-turnover="${t.id}" style="cursor:pointer"><div class="eyebrow">${esc(t.system_code||'PROJECT')}</div><h3 style="margin:7px 0 3px">${esc(t.name)}</h3><div class="muted" style="font-size:11px">${esc(t.system_name||'Project-wide package')}</div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:17px"><div class="score-ring" style="--p:${Number(t.readiness_percent||0)}"><b>${Number(t.readiness_percent||0)}%</b></div><div style="text-align:right">${pill(t.status)}<div class="muted" style="margin-top:8px;font-size:11px">${t.complete_items||0}/${t.required_items||0} required items</div></div></div></div>`).join('')}</div>`:'<div class="card empty">Create the first turnover package for a system.</div>'}`}


function myWorkView(){const m=state.myWork||{},items=[...(m.defects||[]).map(x=>({kind:'Punch',title:x.title,project:x.project_code,asset:x.equipment_tag,status:x.status,due:x.due_date,priority:x.category==='A'?'critical':'high',id:x.id,open:'defect'})),...(m.inspections||[]).map(x=>({kind:'Test',title:x.title,project:x.project_code,asset:x.equipment_tag,status:x.status,due:x.updated_at,priority:'normal',id:x.id,open:'inspection'})),...(m.actions||[]).map(x=>({kind:'Action',title:x.title,project:x.project_code,asset:x.equipment_tag,status:x.status,due:x.due_at,priority:x.priority||'normal',id:x.id,open:'action'}))];return `${hero('My Work','One field queue: what you personally need to complete next','<button class="btn btn-primary" id="quickTest">+ Start field test</button>')}<div class="cards" style="grid-template-columns:repeat(4,1fr)">${card('Assigned tests',(m.inspections||[]).length,'Open QA / commissioning','blue')}${card('Assigned punch',(m.defects||[]).length,'Items requiring action',(m.defects||[]).some(x=>x.category==='A')?'red':'amber')}${card('Actions',(m.actions||[]).length,'PM / field actions','amber')}${card('Witness upcoming',(m.witness||[]).length,'Requested / scheduled','green')}</div>${items.length?`<div class="table-wrap"><table><thead><tr><th>Priority</th><th>Type</th><th>Work item</th><th>Project</th><th>Asset</th><th>Status</th><th>Due / updated</th></tr></thead><tbody>${items.map(x=>`<tr ${x.open==='defect'?`data-defect="${x.id}"`:x.open==='inspection'?`data-inspection="${x.id}"`:''} style="cursor:${x.open==='action'?'default':'pointer'}"><td>${pill(x.priority)}</td><td>${esc(x.kind)}</td><td><strong>${esc(x.title)}</strong></td><td>${esc(x.project||'—')}</td><td>${esc(x.asset||'—')}</td><td>${pill(x.status)}</td><td>${fmtDate(x.due)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="card empty">Nothing assigned to you. Your personal field queue is clear.</div>'}`}

function matrixCell(v,label){const n=Math.max(0,Math.min(100,Number(v||0)));const cls=n===100?'matrix-good':n>=75?'matrix-near':n>0?'matrix-risk':'matrix-empty';return `<div class="matrix-cell ${cls}"><b>${n}%</b><span>${esc(label)}</span></div>`}
function matrixView(){if(!state.projectId)return `${hero('Completion Matrix','Select a project to see every system and every readiness gate')}<div class="card empty">The matrix becomes the PM/Cx meeting screen: system by system, install through turnover.</div>`;return `${hero('Completion Matrix','One live matrix from installation to handover','<button class="btn" id="refreshMatrix">Refresh matrix</button>')}<div class="banner"><div>▦</div><div><strong>No more spreadsheet completion trackers.</strong><p>Every system is scored from equipment completion, approved QA/Cx tests, BMS proof, Category A punch and turnover evidence.</p></div></div>${state.matrix.length?`<div class="table-wrap matrix-wrap"><table><thead><tr><th>System</th><th>Install</th><th>QA / Cx</th><th>BMS I/O</th><th>Cat A</th><th>Turnover</th><th>Readiness</th></tr></thead><tbody>${state.matrix.map(s=>`<tr><td><strong>${esc(s.code)}</strong><br><span class="muted">${esc(s.name)}</span></td><td>${matrixCell(s.install_percent,'install')}</td><td>${matrixCell(s.qa_percent,'tests')}</td><td>${matrixCell(s.io_percent,'I/O')}</td><td>${s.punch_clear?'<div class="gate-pass">CLEAR</div>':`<div class="gate-block">${Number(s.cat_a||0)} OPEN</div>`}</td><td>${matrixCell(s.turnover_percent,'handover')}</td><td><div class="score-big ${Number(s.readiness_score)>=90?'green':Number(s.readiness_score)>=70?'amber':'red'}">${Number(s.readiness_score||0)}%</div></td></tr>`).join('')}</tbody></table></div>`:'<div class="card empty">Create commissioning systems to activate the live completion matrix.</div>'}`}

function evidenceView(){if(!state.projectId)return `${hero('Evidence Hub','Select a project to browse and capture field evidence')}<div class="card empty">Photos, test evidence and closeout files are stored privately in R2 and linked to the asset or record.</div>`;return `${hero('Evidence Hub','Photos and documents tied to the asset, test and defect','<button class="btn btn-primary" id="captureEvidence">+ Capture / upload evidence</button>')}<div class="cards" style="grid-template-columns:repeat(3,1fr)">${card('Evidence files',state.files.length,'Stored in private R2','blue')}${card('Linked to assets',state.files.filter(f=>f.equipment_id).length,'Asset passport evidence','green')}${card('Today',state.files.filter(f=>String(f.created_at||'').slice(0,10)===new Date().toISOString().slice(0,10)).length,'Captured today','amber')}</div>${state.files.length?`<div class="evidence-grid">${state.files.map(f=>`<a class="evidence-card" href="/api/files/${f.id}" target="_blank"><div class="file-icon">${String(f.content_type||'').startsWith('image/')?'▧':'▤'}</div><div><strong>${esc(f.file_name)}</strong><span>${esc(f.equipment_tag||'Project evidence')} • ${fmtTime(f.created_at)}</span><small>${esc(f.uploaded_by_name||'')}</small></div></a>`).join('')}</div>`:'<div class="card empty">No evidence uploaded yet. Use a phone camera to capture the first photo.</div>'}`}

function builderView(){return `${hero('Qx Project Builder','Turn schedules and scope text into a structured commissioning register','<button class="btn" id="importEquipment">⇧ Import equipment CSV</button>')}<div class="grid2"><div class="card"><div class="eyebrow">SMART SETUP</div><h3>Equipment / scope extractor</h3><p class="muted">Paste equipment schedules, scope text or a cleaned drawing extract. Qx identifies common HVAC, electrical and BMS tags and creates a reviewable proposal before anything is applied.</p><div class="field"><label>Source text</label><textarea id="builderText" style="min-height:260px" placeholder="Paste equipment schedule, project scope, sequence summary or drawing text here…"></textarea></div><button class="btn btn-primary" id="runBuilder">Analyse project text</button></div><div class="card" id="builderResult"><div class="empty">Run the builder to generate a proposed equipment structure. Human review remains mandatory against approved project documents.</div></div></div>`}

function closeoutView(){if(!state.projectId)return `${hero('Closeout Studio','Select a project to build the digital handover package')}<div class="card empty">Choose a project first.</div>`;const c=state.copilot||{};return `${hero('Closeout Studio','Digital signoff, controlled documents, live client view and one-click handover dossier','<button class="btn btn-primary" id="openDossier">Generate Handover Dossier</button><button class="btn" id="createShare">Create Client Link</button>')}<div class="cards">${card('Qx forecast',esc(c.forecast||'Analyse project'),`${c.score??'—'} readiness score`,'blue')}${card('Documents',state.documents.length,'Controlled closeout records','green')}${card('Digital signoffs',state.signoffs.length,'Witness / acceptance records','green')}${card('Priority actions',(c.recommendations||[]).length,'Recommended next moves',(c.recommendations||[]).length?'amber':'green')}</div><div class="grid2"><div class="card"><div class="section-head"><h3>Commissioning Copilot</h3><button class="btn btn-small" id="refreshCopilot">Refresh analysis</button></div>${(c.recommendations||[]).length?(c.recommendations||[]).slice(0,8).map((x,i)=>`<div class="action-row"><div class="priority">${i+1}</div><div><b>${esc(x.title)}</b><p>${esc(x.why)}</p></div><button class="btn btn-small" data-route="${esc(x.route)}">Open</button></div>`).join(''):'<div class="empty">Run the analysis to get the next highest-value commissioning actions.</div>'}</div><div class="card"><div class="section-head"><h3>Controlled documents</h3><button class="btn btn-small" id="addDocument">+ Add document</button></div>${state.documents.slice(0,12).map(d=>`<div class="file-row"><div><b>${esc(d.title)}</b><small>${esc(d.doc_type)} • Rev ${esc(d.revision||'—')} • ${esc(d.status)}</small></div>${d.object_file_id?`<a class="btn btn-small" target="_blank" href="/api/files/${d.object_file_id}">Open</a>`:''}</div>`).join('')||'<div class="empty">No controlled documents registered yet.</div>'}</div></div><div class="grid2"><div class="card"><div class="section-head"><h3>Digital acceptance</h3><button class="btn btn-small" id="projectSignoff">+ Project signoff</button></div>${state.signoffs.slice(0,10).map(s=>`<div class="file-row"><div><b>${esc(s.signer_name)}</b><small>${esc(s.signoff_type)} • ${esc(s.signer_company||'')} • ${fmtTime(s.signed_at)}</small></div>${s.signature_data?'<span class="pill approved">SIGNED</span>':''}</div>`).join('')||'<div class="empty">No digital signoffs yet.</div>'}</div><div class="card"><div class="eyebrow">ONE SOURCE OF TRUTH</div><h3>Automatic handover dossier</h3><p class="muted">Qx compiles systems, equipment, QA/Cx records, punch, BMS I/O, turnover, document register and signatures into one printable dossier. Use Print / Save PDF to issue a controlled PDF without rebuilding spreadsheets.</p><button class="btn btn-primary" id="openDossier2">Open live dossier</button></div></div>`}

function reportsView(){if(!state.projectId)return `${hero('Reports & Handover','Select a project to generate live commissioning status reports')}<div class="card empty">Choose a project to create a live executive/commissioning report.</div>`;return `${hero('Reports & Handover','Generate current status without rebuilding spreadsheets','<button class="btn btn-primary" id="printReport">Print / Save PDF</button><button class="btn" id="exportCsv">Export equipment CSV</button>')}<div id="reportSheet" class="report-sheet"><div class="report-brand"><div class="brandmark">QX</div><div><h2>${esc(currentProject()?.code||'')} — ${esc(currentProject()?.name||'')}</h2><p>Commissioning Status & Operational Readiness Report</p></div></div>${dashboardView().replace(/<div class="hero">[\s\S]*?<\/div><\/div>/,'')}</div>`}

function adminView(){if(state.user?.role!=='admin')return `${hero('Admin','Administrator access required')}<div class="card empty">You do not have administrator permission.</div>`;return `${hero('Administration','Users, access and company commissioning standards','<button class="btn btn-primary" id="addUser">+ Add user</button>')}<div class="cards" style="grid-template-columns:repeat(4,1fr)">${card('Users',state.users.length,'Active Qx accounts','blue')}${card('Admins',state.users.filter(u=>u.role==='admin').length,'Platform administrators','green')}${card('Engineers',state.users.filter(u=>u.role==='engineer').length,'Engineering / Cx','blue')}${card('Technicians',state.users.filter(u=>u.role==='technician').length,'Field users','amber')}</div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Created</th></tr></thead><tbody>${state.users.map(u=>`<tr><td><strong>${esc(u.name)}</strong></td><td>${esc(u.email)}</td><td>${pill(u.role)}</td><td>${u.active?pill('active'):pill('inactive')}</td><td>${fmtDate(u.created_at)}</td></tr>`).join('')}</tbody></table></div>`}

function templatesView(){const canEdit=['admin','pm','engineer'].includes(state.user?.role);const list=state.templates;return `${hero('Template Library','Company-controlled QA, ITP, PFC, FPT and IST standards',canEdit?'<button class="btn btn-primary" id="newTemplate">+ New template</button>':'')}<div class="banner"><div>≡</div><div><strong>One controlled library — reusable on every project</strong><p>Open any template to review its checks, hold points and response types. Engineers and PMs can create, edit, duplicate and retire company standards.</p></div></div>${list.length?`<div class="grid3">${list.map(t=>`<button class="card template-card" data-template="${t.id}" style="text-align:left;color:inherit;cursor:pointer"><div style="display:flex;justify-content:space-between;gap:10px"><div class="eyebrow">${esc(t.discipline)} • ${esc(t.stage)}</div>${pill('v'+(t.version||1))}</div><h3 style="margin:8px 0">${esc(t.name)}</h3><p class="muted" style="font-size:12px;line-height:1.5;min-height:55px">${esc(t.description||'No description')}</p><div class="mini-metrics"><span><b>${Number(t.item_count||0)}</b> checks</span><span><b>${Number(t.hold_points||0)}</b> hold points</span></div><div style="margin-top:12px;color:#6ed9ff;font-size:11px;font-weight:800">Open template →</div></button>`).join('')}</div>`:'<div class="card empty">No templates are active. Create the first company standard.</div>'}`}

async function openTemplate(tid){try{const d=await api(`/api/templates/${tid}`);const t=d.template,items=d.items||[];const canEdit=['admin','pm','engineer'].includes(state.user?.role);modal(t.name,`<div class="banner"><div>≡</div><div><strong>${esc(t.discipline)} • ${esc(t.stage)} • Version ${Number(t.version||1)}</strong><p>${esc(t.description||'')}</p></div></div><div class="actions" style="margin-bottom:12px">${state.projectId?'<button class="btn btn-primary" id="startFromTemplate">▶ Start test</button>':''}${canEdit?'<button class="btn" id="editTemplateMeta">Edit details</button><button class="btn" id="duplicateTemplate">Duplicate</button><button class="btn" id="addTemplateItem">+ Add check</button><button class="btn" id="archiveTemplate">Archive</button>':''}</div>${items.length?`<div class="table-wrap"><table><thead><tr><th>#</th><th>Section</th><th>Check / Requirement</th><th>Response</th><th>Mandatory</th><th>Hold</th>${canEdit?'<th></th>':''}</tr></thead><tbody>${items.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.section||'Checks')}</td><td><strong>${esc(x.item_text)}</strong></td><td>${esc((x.response_type||'pass_fail_na').replaceAll('_',' '))}</td><td>${x.mandatory?'Yes':'No'}</td><td>${x.hold_point?'<span class="pill fail">HOLD</span>':'—'}</td>${canEdit?`<td><button class="btn btn-small" data-edit-template-item="${x.id}">Edit</button></td>`:''}</tr>`).join('')}</tbody></table></div>`:'<div class="card empty">This template has no checks yet.</div>'}`,true);
if($('#startFromTemplate'))$('#startFromTemplate').onclick=()=>{const project=currentProject();if(!project)return toast('Select a project first');const equipOpts=state.equipment.map(e=>`<option value="${e.id}">${esc(e.tag)} — ${esc(e.name)}</option>`).join('');modal(`Start ${t.name}`,`<form id="startTplForm"><div class="field"><label>Test title</label><input name="title" value="${esc(t.name)}" required></div><div class="field"><label>Equipment / asset (optional)</label><select name="equipment_id"><option value="">Project / system level</option>${equipOpts}</select></div><div class="field"><label>Assign to (optional)</label><select name="assigned_to"><option value="">Unassigned</option>${state.users.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select></div><button class="btn btn-primary">Create & open test</button></form>`);$('#startTplForm').onsubmit=async e=>{e.preventDefault();try{const x=Object.fromEntries(new FormData(e.target));x.project_id=state.projectId;x.template_id=t.id;const r=await api('/api/inspections',{method:'POST',body:JSON.stringify(x)});$('#modal').remove();await loadAll();state.view='inspections';render();openInspection(r.id)}catch(err){toast(err.message)}}};
if($('#editTemplateMeta'))$('#editTemplateMeta').onclick=()=>openTemplateForm(t);
if($('#duplicateTemplate'))$('#duplicateTemplate').onclick=async()=>{try{const r=await api(`/api/templates/${t.id}/duplicate`,{method:'POST',body:JSON.stringify({})});$('#modal').remove();await loadAll();render();toast('Template duplicated');openTemplate(r.id)}catch(err){toast(err.message)}};
if($('#addTemplateItem'))$('#addTemplateItem').onclick=()=>openTemplateItemForm(t,null);
if($('#archiveTemplate'))$('#archiveTemplate').onclick=async()=>{if(!confirm(`Archive ${t.name}? Existing completed tests are not affected.`))return;try{await api(`/api/templates/${t.id}`,{method:'DELETE'});$('#modal').remove();await loadAll();render();toast('Template archived')}catch(err){toast(err.message)}};
$$('[data-edit-template-item]').forEach(b=>b.onclick=()=>openTemplateItemForm(t,items.find(x=>x.id===b.dataset.editTemplateItem)));
}catch(err){toast(err.message)}}

function openTemplateForm(existing=null){const t=existing||{};modal(existing?'Edit template':'New template',`<form id="templateForm"><div class="formgrid"><div class="field span2"><label>Name</label><input name="name" value="${esc(t.name||'')}" required></div><div class="field"><label>Discipline</label><select name="discipline">${['Electrical','BMS','Mechanical/BMS','Mechanical','Integrated Systems','Life Safety','General'].map(x=>`<option ${x===t.discipline?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Stage</label><select name="stage">${[['qa','QA / ITP'],['prefunctional','Pre-functional'],['commissioning','Commissioning'],['functional','Functional Performance'],['integrated','Integrated Systems Test'],['handover','Handover']].map(([v,l])=>`<option value="${v}" ${v===t.stage?'selected':''}>${l}</option>`).join('')}</select></div><div class="field span2"><label>Description</label><textarea name="description">${esc(t.description||'')}</textarea></div></div><button class="btn btn-primary">${existing?'Save template':'Create template'}</button></form>`);$('#templateForm').onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));const r=await api(existing?`/api/templates/${existing.id}`:'/api/templates',{method:existing?'PATCH':'POST',body:JSON.stringify(data)});$('#modal').remove();await loadAll();render();toast(existing?'Template updated':'Template created');openTemplate(existing?.id||r.id)}catch(err){toast(err.message)}}}

function openTemplateItemForm(template,item=null){const x=item||{};modal(item?'Edit template check':'Add template check',`<form id="templateItemForm"><div class="formgrid"><div class="field"><label>Section</label><input name="section" value="${esc(x.section||'Checks')}" required></div><div class="field"><label>Response type</label><select name="response_type">${[['pass_fail_na','Pass / Fail / N/A'],['text','Text'],['number','Number'],['yes_no','Yes / No']].map(([v,l])=>`<option value="${v}" ${v===x.response_type?'selected':''}>${l}</option>`).join('')}</select></div><div class="field span2"><label>Check / requirement</label><textarea name="item_text" required>${esc(x.item_text||'')}</textarea></div><div class="field"><label><input type="checkbox" name="mandatory" ${x.mandatory!==0?'checked':''}> Mandatory</label></div><div class="field"><label><input type="checkbox" name="hold_point" ${x.hold_point?'checked':''}> Witness / hold point</label></div></div><div class="actions"><button class="btn btn-primary">Save check</button>${item?'<button type="button" class="btn" id="deleteTemplateItem">Delete check</button>':''}</div></form>`);$('#templateItemForm').onsubmit=async e=>{e.preventDefault();try{const fd=new FormData(e.target),data=Object.fromEntries(fd);data.mandatory=fd.has('mandatory');data.hold_point=fd.has('hold_point');await api(item?`/api/template-items/${item.id}`:`/api/templates/${template.id}/items`,{method:item?'PATCH':'POST',body:JSON.stringify(data)});$('#modal').remove();await loadAll();render();toast('Template check saved');openTemplate(template.id)}catch(err){toast(err.message)}};if(item&&$('#deleteTemplateItem'))$('#deleteTemplateItem').onclick=async()=>{if(!confirm('Delete this check from the template?'))return;try{await api(`/api/template-items/${item.id}`,{method:'DELETE'});$('#modal').remove();await loadAll();render();toast('Check deleted');openTemplate(template.id)}catch(err){toast(err.message)}}}


function modal(title,body,wide=false){
  const existing=$('#modal'); if(existing) existing.remove();
  document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal" role="presentation"><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><div><div class="eyebrow">ELLIOT QX</div><h2>${esc(title)}</h2></div><button type="button" class="modal-x" id="closeModal" aria-label="Close">×</button></div>${body}</div></div>`);
  const overlay=$('#modal'), close=()=>{ if(overlay?.isConnected) overlay.remove(); document.removeEventListener('keydown',onKey); };
  const onKey=e=>{ if(e.key==='Escape') close(); };
  $('#closeModal')?.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();close()});
  overlay?.addEventListener('click',e=>{ if(e.target===overlay) close(); });
  document.addEventListener('keydown',onKey);
}
function projectOptions(){return state.projects.map(p=>`<option value="${p.id}" ${p.id===state.projectId?'selected':''}>${esc(p.code)} — ${esc(p.name)}</option>`).join('')}
function systemOptions(){return state.systems.map(s=>`<option value="${s.id}">${esc(s.code)} — ${esc(s.name)}</option>`).join('')}
function equipmentOptions(){return state.equipment.map(e=>`<option value="${e.id}">${esc(e.tag)} — ${esc(e.name)}</option>`).join('')}
function userOptions(){return state.users.map(u=>`<option value="${u.id}">${esc(u.name)} — ${esc(u.role)}</option>`).join('')}

function wireActions(){
  $('#projectPicker').onchange=async e=>{state.projectId=e.target.value;state.query='';await loadAll();render()};
  $('#menuBtn')?.addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
  $$('.navbtn[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;state.query='';$('#sidebar').classList.remove('open');render()});
  $('#logout').onclick=async()=>{await api('/api/auth/logout',{method:'POST'}).catch(()=>{});state.user=null;renderLogin(true)};
  $('#searchBox')?.addEventListener('input',e=>{state.query=e.target.value;renderKeepFocus()});
  $('#eqStatus')?.addEventListener('change',e=>{state.filters.eqStatus=e.target.value;render()});
  $('#addProject')?.addEventListener('click',openProjectForm); $('#addSystem')?.addEventListener('click',openSystemForm); $('#addEquipment')?.addEventListener('click',openEquipmentForm); $('#addInspection')?.addEventListener('click',openInspectionForm); $('#quickTest')?.addEventListener('click',openInspectionForm); $('#addDefect')?.addEventListener('click',openDefectForm); $('#quickDefect')?.addEventListener('click',openDefectForm); $('#importPoints')?.addEventListener('click',openPointImport); $('#addTurnover')?.addEventListener('click',openTurnoverForm); $('#addWitness')?.addEventListener('click',openWitnessForm); $('#importEquipment')?.addEventListener('click',openEquipmentImport); $('#captureEvidence')?.addEventListener('click',openEvidenceUpload); $('#scanAsset')?.addEventListener('click',openScanner); $('#runBuilder')?.addEventListener('click',runBuilder); $('#printReport')?.addEventListener('click',()=>window.print()); $('#exportCsv')?.addEventListener('click',exportEquipmentCsv); $('#addUser')?.addEventListener('click',openUserForm); $('#refreshMatrix')?.addEventListener('click',async()=>{await loadAll();render()});
  $$('[data-inspection]').forEach(r=>r.onclick=()=>openInspection(r.dataset.inspection)); $$('[data-point]').forEach(r=>r.onclick=()=>openPoint(r.dataset.point)); $$('[data-defect]').forEach(r=>r.onclick=()=>openDefect(r.dataset.defect)); $$('[data-turnover]').forEach(r=>r.onclick=()=>openTurnover(r.dataset.turnover)); $$('[data-passport]').forEach(b=>b.onclick=()=>openAssetPassport(b.dataset.passport));
}
function renderKeepFocus(){const pos=$('#searchBox')?.selectionStart;render();const box=$('#searchBox');if(box){box.focus();box.setSelectionRange(pos,pos)}}


function riskPill(v){return `<span class="risk-pill ${esc(v)}">${esc(String(v||'').replaceAll('_',' '))}</span>`}
function portfolioView(){const rows=state.portfolio||[];const critical=rows.filter(x=>x.risk==='critical').length,avg=rows.length?Math.round(rows.reduce((n,x)=>n+Number(x.readiness_score||0),0)/rows.length):0;return `${hero('Portfolio Control Tower','Cross-project readiness, risk and handover position for Elliot Controls')}<div class="cards">${card('Active projects',rows.length,'Live projects in Qx','blue')}${card('Portfolio readiness',`${avg}%`,'Weighted completion intelligence',avg>=85?'green':'amber')}${card('Critical projects',critical,'Category A / failed BMS blockers',critical?'red':'green')}${card('Open defects',rows.reduce((n,x)=>n+Number(x.open_defects||0),0),'Across portfolio','amber')}</div><div class="portfolio-grid">${rows.map(p=>`<button class="project-tile" data-open-project="${p.id}"><div class="tile-top"><div><span>${esc(p.code)}</span><h3>${esc(p.name)}</h3></div>${riskPill(p.risk)}</div><div class="score-line"><strong>${p.readiness_score}%</strong>${progress(p.readiness_score)}</div><div class="mini-metrics"><span>Assets <b>${p.asset_percent}%</b></span><span>Tests <b>${p.test_percent}%</b></span><span>BMS <b>${p.bms_percent}%</b></span><span>Turnover <b>${p.turnover_percent}%</b></span></div><div class="tile-foot"><span>${p.cat_a} Cat A</span><span>${p.failed_points} failed I/O</span><span>${p.witness_open} witness</span></div></button>`).join('')||'<div class="card empty">Create your first project to start the portfolio view.</div>'}</div>`}
function fieldHubView(){if(!state.projectId)return `${hero('Field Hub','The fastest route from site condition to verified commissioning record')}<div class="card empty">Select a project first.</div>`;const pack=localStorage.getItem(`qx-offline-pack:${state.projectId}`);let meta=null;try{meta=JSON.parse(pack||'null')}catch{}const q=getQueue().length;return `${hero('Field Hub','Large touch targets, scan-first workflow and offline project packs',`<button class="btn btn-primary" id="downloadPack">${meta?'Refresh':'Download'} offline pack</button>`)}<div class="field-status-strip"><div><span>Connection</span><b>${navigator.onLine?'LIVE':'OFFLINE'}</b></div><div><span>Queued updates</span><b>${q}</b></div><div><span>Offline pack</span><b>${meta?fmtTime(meta.generated_at):'Not downloaded'}</b></div><div><span>Open Cat A</span><b>${state.defects.filter(x=>x.category==='A'&&!['closed','verified'].includes(x.status)).length}</b></div></div><div class="field-launcher"><button data-route="equipment"><i>▣</i><b>Scan / Assets</b><span>Open asset passport in seconds</span></button><button data-route="inspections"><i>✓</i><b>QA / ITP</b><span>Complete inspections and tests</span></button><button data-route="points"><i>↯</i><b>BMS I/O</b><span>Point-to-point commissioning</span></button><button data-route="defects"><i>!</i><b>Punch</b><span>Raise and close defects</span></button><button data-route="observations"><i>●</i><b>Observation</b><span>Capture site condition / note</span></button><button id="captureEvidence"><i>◫</i><b>Evidence</b><span>Photo or document to asset</span></button></div><div class="grid2"><div class="card"><div class="section-head"><h3>My next work</h3><span>${(state.myWork.actions?.length||0)+(state.myWork.inspections?.length||0)+(state.myWork.defects?.length||0)} items</span></div>${[...(state.myWork.actions||[]).slice(0,3),...(state.myWork.inspections||[]).slice(0,3)].map(x=>`<div class="activity-item"><b>${esc(x.title||x.name||'Assigned work')}</b><small>${esc(x.status||'open')}</small></div>`).join('')||'<div class="empty">No assigned work.</div>'}</div><div class="card"><div class="section-head"><h3>Readiness blockers</h3></div>${(state.equipmentReadiness||[]).filter(x=>!x.ready&&x.blockers?.length).slice(0,6).map(x=>`<div class="activity-item"><b>${esc(x.tag)} — ${esc(x.name)}</b><small>${esc(x.blockers.join(' • '))}</small></div>`).join('')||'<div class="empty">No asset blockers detected.</div>'}</div></div>`}
function observationsView(){if(!state.projectId)return `${hero('Field Observations','Capture site conditions, design comments and construction observations')}<div class="card empty">Select a project first.</div>`;const rows=state.observations||[];return `${hero('Field Observations','One register for observations before they become defects','<button class="btn btn-primary" id="addObservation">+ Observation</button>')}<div class="cards">${card('Open',rows.filter(x=>x.status==='open').length,'Awaiting action','amber')}${card('Critical',rows.filter(x=>x.severity==='critical'&&x.status!=='closed').length,'Immediate review','red')}${card('Total',rows.length,'Captured field intelligence','blue')}</div><div class="table-wrap"><table><thead><tr><th>Type</th><th>Observation</th><th>Asset/System</th><th>Owner</th><th>Severity</th><th>Status</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.observation_type)}</td><td><strong>${esc(x.title)}</strong><br><span class="muted">${esc(x.description||'')}</span></td><td>${esc(x.equipment_tag||x.system_code||'—')}</td><td>${esc(x.assigned_name||'Unassigned')}</td><td>${pill(x.severity)}</td><td>${pill(x.status)}</td></tr>`).join('')||'<tr><td colspan="6">No observations.</td></tr>'}</tbody></table></div>`}
function plannerView(){if(!state.projectId)return `${hero('Commissioning Plan','Milestones from install readiness through integrated systems testing and handover')}<div class="card empty">Select a project first.</div>`;const rows=state.milestones||[];return `${hero('Commissioning Plan','Milestone and gate control for the commissioning programme','<button class="btn btn-primary" id="addMilestone">+ Milestone</button>')}<div class="timeline">${rows.map(m=>`<div class="timeline-row ${m.status}"><div class="timeline-date">${fmtDate(m.target_at)}</div><div class="timeline-dot"></div><div class="timeline-card"><div><span>${esc(m.phase)}</span><h3>${esc(m.name)}</h3><p>${esc(m.system_code||'Project-wide')} • ${esc(m.owner_name||'Unassigned')}</p></div>${pill(m.status)}</div></div>`).join('')||'<div class="card empty">No milestones yet. Add energisation, PFC, FPT, IST, witness and handover gates.</div>'}</div>`}
function smartTemplatesView(){if(!state.projectId)return `${hero('Smart Template Builder','Turn project requirements into a reviewable QA / commissioning test draft')}<div class="card empty">Select a project first.</div>`;return `${hero('Smart Template Builder','Generate project-specific ITP, PFC and FPT drafts from scope, specification or sequence text')}<div class="grid2"><div class="card"><form id="smartForm"><div class="formgrid"><div class="field span2"><label>Template name</label><input name="name" required placeholder="AHU Functional Performance Test — Project Specific"></div><div class="field"><label>Discipline</label><select name="discipline"><option>BMS</option><option>Electrical</option><option>Mechanical/BMS</option><option>Integrated Systems</option></select></div><div class="field"><label>Stage</label><select name="stage"><option value="qa">QA / ITP</option><option value="prefunctional">Pre-functional</option><option value="functional" selected>Functional</option><option value="integrated">Integrated systems</option></select></div><div class="field span2"><label>Paste approved scope / sequence / specification extract</label><textarea name="source_text" style="min-height:280px" placeholder="Paste the relevant project requirements here..."></textarea></div></div><button class="btn btn-primary">Build test draft</button></form></div><div class="card" id="smartResult">${state.smartForm?smartProposalHtml(state.smartForm):'<div class="empty">Qx will create a reviewable test draft. Approved project documents remain the authority.</div>'}</div></div>`}
function smartProposalHtml(r){const p=r.proposal||{};return `<div class="eyebrow">REVIEW BEFORE APPLYING</div><h2>${esc(p.name||'Draft')}</h2><p class="muted">${esc(p.warning||'')}</p><div class="smart-checks">${(p.items||[]).map((x,i)=>`<div><span>${i+1}</span><p><b>${esc(x.section)}</b><br>${esc(x.item_text)}</p>${x.hold_point?'<em>HOLD</em>':''}</div>`).join('')}</div><button class="btn btn-primary" id="applySmart" data-job="${esc(r.id)}">Add to Template Library</button>`}
async function loadV8(){try{await api('/api/v8/ensure',{method:'POST',body:'{}'});state.v8ready=true;const pf=await api('/api/portfolio');state.portfolio=pf.projects||[];if(state.projectId){const q=`?project_id=${encodeURIComponent(state.projectId)}`;const [o,m,r,c]=await Promise.all([api(`/api/observations${q}`),api(`/api/milestones${q}`),api(`/api/equipment-readiness${q}`),api(`/api/sync/conflicts${q}`)]);state.observations=o.observations||[];state.milestones=m.milestones||[];state.equipmentReadiness=r.equipment||[];state.syncConflicts=c.conflicts||[];const pack=localStorage.getItem(`qx-offline-pack:${state.projectId}`);try{state.offlinePackAt=JSON.parse(pack||'null')?.generated_at||null}catch{state.offlinePackAt=null}}else{state.observations=[];state.milestones=[];state.equipmentReadiness=[];state.syncConflicts=[]}}catch(e){console.warn('V8 extensions unavailable',e)}}
function openObservationForm(){modal('New field observation',`<form id="obsForm"><div class="formgrid"><div class="field span2"><label>Title</label><input name="title" required placeholder="Access panel clashes with BMS sensor location"></div><div class="field"><label>Type</label><select name="observation_type"><option value="field">Field observation</option><option value="design">Design review</option><option value="construction">Construction review</option><option value="client">Client comment</option></select></div><div class="field"><label>Severity</label><select name="severity"><option>normal</option><option>high</option><option>critical</option></select></div><div class="field"><label>System</label><select name="system_id"><option value="">Project wide</option>${systemOptions()}</select></div><div class="field"><label>Equipment</label><select name="equipment_id"><option value="">None</option>${equipmentOptions()}</select></div><div class="field span2"><label>Description</label><textarea name="description"></textarea></div></div><button class="btn btn-primary">Save observation</button></form>`);$('#obsForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.project_id=state.projectId;await api('/api/observations',{method:'POST',body:JSON.stringify(d)});$('#modal').remove();await loadAll();render();toast('Observation captured')}}
function openMilestoneForm(){modal('Add commissioning milestone',`<form id="mileForm"><div class="formgrid"><div class="field span2"><label>Milestone / gate</label><input name="name" required placeholder="AHU systems ready for FPT"></div><div class="field"><label>Phase</label><select name="phase"><option>installation</option><option>pre-energisation</option><option>commissioning</option><option>functional testing</option><option>IST</option><option>witness</option><option>handover</option></select></div><div class="field"><label>Target date</label><input name="target_at" type="date"></div><div class="field"><label>System</label><select name="system_id"><option value="">Project wide</option>${systemOptions()}</select></div><div class="field"><label>Owner</label><select name="owner_id"><option value="">Unassigned</option>${userOptions()}</select></div></div><button class="btn btn-primary">Add milestone</button></form>`);$('#mileForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.project_id=state.projectId;await api('/api/milestones',{method:'POST',body:JSON.stringify(d)});$('#modal').remove();await loadAll();render();toast('Milestone added')}}
async function downloadOfflinePack(){if(!state.projectId)return toast('Select a project');try{const pack=await api(`/api/offline/pack?project_id=${encodeURIComponent(state.projectId)}`);localStorage.setItem(`qx-offline-pack:${state.projectId}`,JSON.stringify(pack));for(const [name,data] of Object.entries({projects:{projects:[pack.project]},systems:{systems:pack.systems},equipment:{equipment:pack.equipment},templates:{templates:pack.templates},inspections:{inspections:pack.inspections},defects:{defects:pack.defects},points:{points:pack.points},turnover:{packages:pack.turnover},witness:{witness:pack.witness},actions:{actions:pack.actions}})){const pathMap={projects:'/api/projects',systems:`/api/systems?project_id=${state.projectId}`,equipment:`/api/equipment?project_id=${state.projectId}`,templates:'/api/templates',inspections:`/api/inspections?project_id=${state.projectId}`,defects:`/api/defects?project_id=${state.projectId}`,points:`/api/bms-points?project_id=${state.projectId}`,turnover:`/api/turnover?project_id=${state.projectId}`,witness:`/api/witness?project_id=${state.projectId}`,actions:`/api/actions?project_id=${state.projectId}`};localStorage.setItem(API_CACHE+pathMap[name],JSON.stringify({at:Date.now(),data}))}state.offlinePackAt=pack.generated_at;render();toast('Offline project pack ready')}catch(e){toast(e.message)}}

function notificationsView(){const n=state.notifications||[];return `${hero('Alerts & Escalations','One priority inbox for overdue, blocking and commissioning-critical work','<button class="btn btn-primary" id="refreshAlerts">Refresh risk scan</button>')}<div class="cards">${card('Critical',n.filter(x=>x.severity==='critical'&&!x.read_at).length,'Requires immediate action','red')}${card('Unread',n.filter(x=>!x.read_at).length,'Across selected project','amber')}${card('Open alerts',n.length,'Auto-generated from live project data','blue')}</div><div class="card">${n.length?n.map(x=>`<div class="activity-item"><b>${esc(x.title)}</b><p>${esc(x.message)}</p><small>${esc(x.severity.toUpperCase())} • ${fmtTime(x.created_at)}</small></div>`).join(''):'<div class="empty">No active escalations. Qx will generate them from overdue actions, Category A punch, failed BMS points and witness holds.</div>'}</div>`}
function drawingsView(){if(!state.projectId)return `${hero('Drawings & Markups','Drawing-centric QA with issue pins and field evidence')}<div class="card empty">Select a project to manage drawings.</div>`;const rows=state.drawings||[];return `${hero('Drawings & Markups','Controlled drawing register with field issue pins','<button class="btn btn-primary" id="addDrawing">+ Register drawing</button>')}<div class="banner"><div>⌗</div><div><strong>Drawing-first commissioning</strong><p>Register approved drawings, open them from R2 evidence, and pin defects or observations to a sheet coordinate so field teams can find the exact location.</p></div></div><div class="table-wrap"><table><thead><tr><th>Drawing</th><th>Title</th><th>Rev</th><th>Discipline</th><th>Pins</th><th>Updated</th></tr></thead><tbody>${rows.map(x=>`<tr data-drawing="${x.id}" style="cursor:pointer"><td><strong>${esc(x.drawing_no)}</strong></td><td>${esc(x.title)}</td><td>${esc(x.revision||'—')}</td><td>${esc(x.discipline||'—')}</td><td>${x.pin_count||0}</td><td>${fmtTime(x.updated_at)}</td></tr>`).join('')||'<tr><td colspan="6">No drawings registered yet.</td></tr>'}</tbody></table></div>`}
async function loadV7(){try{await api('/api/v7/ensure',{method:'POST',body:'{}'});state.v7ready=true;const q=state.projectId?`?project_id=${encodeURIComponent(state.projectId)}`:'';const [n,d]=await Promise.all([api(`/api/notifications${q}`),state.projectId?api(`/api/drawings${q}`):Promise.resolve({drawings:[]})]);state.notifications=n.notifications||[];state.drawings=d.drawings||[]}catch(e){console.warn('V7 extensions unavailable',e)}}
function openDrawingForm(){modal('Register controlled drawing',`<form id="drawingForm"><div class="formgrid"><div class="field"><label>Drawing number</label><input name="drawing_no" required placeholder="E-401"></div><div class="field"><label>Revision</label><input name="revision" placeholder="C"></div><div class="field span2"><label>Title</label><input name="title" required placeholder="MSSB / BMS Layout"></div><div class="field"><label>Discipline</label><select name="discipline"><option>Electrical</option><option>BMS</option><option>Mechanical</option><option>Controls</option><option>General</option></select></div><div class="field"><label>Existing R2 file ID (optional)</label><input name="file_id" placeholder="Link an uploaded PDF/image"></div></div><button class="btn btn-primary">Register drawing</button></form>`);$('#drawingForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.project_id=state.projectId;await api('/api/drawings',{method:'POST',body:JSON.stringify(d)});$('#modal').remove();await loadV7();render();toast('Drawing registered')}}
async function openDrawing(id){const d=await api(`/api/drawings/${id}`);const x=d.drawing;modal(`${x.drawing_no} — ${x.title}`,`<div class="banner"><div>⌗</div><div><strong>Revision ${esc(x.revision||'—')}</strong><p>${esc(x.discipline||'')} • ${d.pins.length} field pin(s)</p></div></div>${x.file_id?`<a class="btn" target="_blank" href="/api/files/${x.file_id}">Open source drawing</a>`:''}<div class="card" style="margin-top:14px"><h3>Add field pin</h3><form id="pinForm"><div class="formgrid"><div class="field span2"><label>Issue / observation</label><input name="title" required placeholder="VSD isolator location differs from drawing"></div><div class="field"><label>X position %</label><input name="x" type="number" min="0" max="100" value="50"></div><div class="field"><label>Y position %</label><input name="y" type="number" min="0" max="100" value="50"></div><div class="field"><label>Severity</label><select name="severity"><option>normal</option><option>high</option><option>critical</option></select></div></div><button class="btn btn-primary">Pin to drawing</button></form></div><div class="section-head"><h3>Markup pins</h3></div>${d.pins.map(p=>`<div class="activity-item"><b>${esc(p.title)}</b><p>${esc(p.severity)} • X ${p.x_percent}% / Y ${p.y_percent}%</p><small>${fmtTime(p.created_at)}</small></div>`).join('')||'<div class="empty">No pins yet.</div>'}`,true);$('#pinForm').onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target));await api(`/api/drawings/${id}/pins`,{method:'POST',body:JSON.stringify(p)});$('#modal').remove();await loadV7();openDrawing(id)}}
function render(){const views={portfolio:portfolioView,dashboard:dashboardView,fieldhub:fieldHubView,notifications:notificationsView,drawings:drawingsView,planner:plannerView,observations:observationsView,smarttemplates:smartTemplatesView,mywork:myWorkView,matrix:matrixView,projects:projectsView,systems:systemsView,intelligence:intelligenceView,equipment:equipmentView,builder:builderView,inspections:inspectionsView,points:pointsView,defects:defectsView,evidence:evidenceView,witness:witnessView,turnover:turnoverView,reports:reportsView,closeout:closeoutView,templates:templatesView,admin:adminView};app.innerHTML=shell((views[state.view]||dashboardView)());wireActions();updateQueueBadge()}

function formSubmit(form,path,after){form.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));try{await api(path,{method:'POST',body:JSON.stringify(data)});$('#modal')?.remove();await loadAll();render();toast(after||'Saved')}catch(err){form.insertAdjacentHTML('afterbegin',`<div class="error">${esc(err.message)}</div>`)}}}
async function loadCloseout(){if(!state.projectId)return;try{const [c,d,s]=await Promise.all([api(`/api/copilot/project?project_id=${encodeURIComponent(state.projectId)}`),api(`/api/documents?project_id=${encodeURIComponent(state.projectId)}`),api(`/api/signoffs?project_id=${encodeURIComponent(state.projectId)}`)]);state.copilot=c;state.documents=d.documents||[];state.signoffs=s.signoffs||[]}catch(e){toast(e.message)}}
function wireCloseout(){if(state.view!=='closeout')return;loadCloseout().then(()=>{if(state.view==='closeout')render()}).catch(()=>{});}
function openSignature(){modal('Project digital acceptance',`<form id="signForm"><div class="formgrid"><div class="field"><label>Signer name</label><input name="signer_name" required></div><div class="field"><label>Company</label><input name="signer_company"></div><div class="field"><label>Role</label><input name="signer_role" placeholder="Commissioning Manager / Client"></div><div class="field"><label>Signoff type</label><select name="signoff_type"><option value="project_acceptance">Project acceptance</option><option value="witness">Witness acceptance</option><option value="handover">Handover acceptance</option></select></div><div class="field span2"><label>Declaration</label><textarea name="declaration">I confirm the listed commissioning/closeout status has been reviewed and accepted subject to recorded outstanding items.</textarea></div></div><div class="field"><label>Signature — draw below</label><canvas id="sigCanvas" width="700" height="180" style="width:100%;height:180px;background:white;border-radius:8px;touch-action:none"></canvas></div><button type="button" class="btn" id="clearSig">Clear</button> <button class="btn btn-primary">Save signed acceptance</button></form>`,true);const c=$('#sigCanvas'),ctx=c.getContext('2d');ctx.lineWidth=2.5;ctx.lineCap='round';ctx.strokeStyle='#111';let down=false;const pos=e=>{const r=c.getBoundingClientRect(),q=e.touches?.[0]||e;return[(q.clientX-r.left)*c.width/r.width,(q.clientY-r.top)*c.height/r.height]};const start=e=>{down=true;const [x,y]=pos(e);ctx.beginPath();ctx.moveTo(x,y);e.preventDefault()};const move=e=>{if(!down)return;const [x,y]=pos(e);ctx.lineTo(x,y);ctx.stroke();e.preventDefault()};const end=()=>down=false;c.onpointerdown=start;c.onpointermove=move;c.onpointerup=end;c.onpointerleave=end;$('#clearSig').onclick=()=>ctx.clearRect(0,0,c.width,c.height);$('#signForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.project_id=state.projectId;d.entity_type='project';d.entity_id=state.projectId;d.signature_data=c.toDataURL('image/png');try{await api('/api/signoffs',{method:'POST',body:JSON.stringify(d)});$('#modal').remove();await loadCloseout();render();toast('Digital acceptance saved')}catch(err){toast(err.message)}}}
function openDocumentForm(){modal('Add controlled document',`<form id="docForm"><div class="formgrid"><div class="field"><label>Document number</label><input name="document_no"></div><div class="field"><label>Revision</label><input name="revision" placeholder="A / P01 / 1"></div><div class="field span2"><label>Title</label><input name="title" required></div><div class="field"><label>Type</label><select name="doc_type"><option>As-built drawing</option><option>O&M manual</option><option>Commissioning report</option><option>Electrical test record</option><option>BMS backup</option><option>Training record</option><option>Certificate</option><option>Other</option></select></div><div class="field"><label>Status</label><select name="status"><option value="current">Current</option><option value="draft">Draft</option><option value="superseded">Superseded</option></select></div><div class="field span2"><label>File</label><input id="docFile" type="file" required></div></div><button class="btn btn-primary">Upload & register</button></form>`);$('#docForm').onsubmit=async e=>{e.preventDefault();const f=$('#docFile').files[0];if(!f)return;try{const qs=new URLSearchParams({project_id:state.projectId});const r=await fetch(`/api/files?${qs}`,{method:'POST',body:f,credentials:'same-origin',headers:{'content-type':f.type||'application/octet-stream','x-file-name':f.name}});const fd=await r.json();if(!r.ok)throw new Error(fd.error||'Upload failed');const d=Object.fromEntries(new FormData(e.target));delete d[''];d.project_id=state.projectId;d.object_file_id=fd.id;await api('/api/documents',{method:'POST',body:JSON.stringify(d)});$('#modal').remove();await loadCloseout();render();toast('Controlled document registered')}catch(err){toast(err.message)}}}

