function openTurnoverForm(){if(!state.projects.length)return toast('Create a project first');modal('Create turnover package',`<form id="f"><div class="field"><label>Project</label><select name="project_id" required>${projectOptions()}</select></div><div class="field"><label>System</label><select name="system_id"><option value="">Project-wide</option>${systemOptions()}</select></div><div class="field"><label>Package name</label><input name="name" required placeholder="BMS System Completion Package"></div><button class="btn btn-primary">Create package with Qx readiness gates</button></form>`);formSubmit($('#f'),'/api/turnover','Turnover package created')}
