function openEquipmentImport(){if(!state.projectId)return toast('Select a project first');modal('Import equipment register',`<div class="banner"><div>⇧</div><div><strong>Bulk asset setup</strong><p>Paste CSV from Excel. Required: tag,name. Optional: system,subsystem,building,level,area,equipment_type,manufacturer,model,serial_number.</p></div></div><div class="field"><label>CSV data</label><textarea id="eqCsv" style="min-height:280px" placeholder="tag,name,system,level,equipment_type\nAHU-01,Air Handling Unit 01,SYS-AHU,L01,AHU"></textarea></div><button class="btn btn-primary" id="doEqImport">Import assets</button>`,true);$('#doEqImport').onclick=async()=>{try{const equipment=parseCSV($('#eqCsv').value);if(!equipment.length)throw new Error('No valid CSV rows found');const r=await api('/api/equipment/import',{method:'POST',body:JSON.stringify({project_id:state.projectId,equipment})});$('#modal').remove();await loadAll();render();toast(`${r.created} assets imported • ${r.skipped} skipped`)}catch(e){toast(e.message)}}}

function openEvidenceUpload(){if(!state.projectId)return toast('Select a project first');modal('Capture / upload evidence',`<form id="evidenceForm"><div class="field"><label>Link to equipment</label><select name="equipment_id"><option value="">Project-level evidence</option>${equipmentOptions()}</select></div><div class="field"><label>Photo / file</label><input id="evidenceFile" type="file" accept="image/*,application/pdf" capture="environment" required></div><button class="btn btn-primary">Upload evidence</button></form>`);$('#evidenceForm').onsubmit=async e=>{e.preventDefault();const file=$('#evidenceFile').files[0];if(!file)return;const eq=new FormData(e.target).get('equipment_id');try{const qs=new URLSearchParams({project_id:state.projectId});if(eq)qs.set('equipment_id',eq);const r=await fetch(`/api/files?${qs}`,{method:'POST',body:file,credentials:'same-origin',headers:{'content-type':file.type||'application/octet-stream','x-file-name':file.name}});const d=await r.json();if(!r.ok)throw new Error(d.error||'Upload failed');$('#modal').remove();await loadAll();render();toast('Evidence uploaded')}catch(err){toast(err.message)}}}

async function openAssetPassport(eid){try{const d=await api(`/api/equipment/${eid}/passport`),e=d.equipment;const ioPass=(d.points||[]).filter(x=>x.overall_status==='pass').length,ioFail=(d.points||[]).filter(x=>x.overall_status==='fail').length,openDef=(d.defects||[]).filter(x=>!['closed','verified'].includes(x.status)).length;modal(`Asset Passport — ${e.tag}`,`<div class="passport-head"><div><div class="eyebrow">${esc(e.project_code)} • ${esc(e.equipment_type||'ASSET')}</div><h2>${esc(e.tag)} — ${esc(e.name)}</h2><p>${esc([e.building,e.level,e.area].filter(Boolean).join(' / ')||'Location not set')}</p></div><div class="passport-score">${pill(e.status)}</div></div><div class="cards" style="grid-template-columns:repeat(4,1fr)">${card('QA / Cx tests',(d.inspections||[]).length,`${(d.inspections||[]).filter(x=>x.status==='approved').length} approved`,'green')}${card('BMS points',(d.points||[]).length,`${ioPass} proven • ${ioFail} failed`,ioFail?'red':'blue')}${card('Open punch',openDef,'Asset-linked defects',openDef?'amber':'green')}${card('Evidence',(d.files||[]).length,'Photos / documents','blue')}</div><div class="grid2"><div class="card"><div class="section-head"><h3>Asset record</h3><button class="btn btn-small" id="copyAssetLink">Copy QR link</button></div><div class="detail-list"><div><span>System</span><b>${esc(e.system||'—')}</b></div><div><span>Manufacturer</span><b>${esc(e.manufacturer||'—')}</b></div><div><span>Model</span><b>${esc(e.model||'—')}</b></div><div><span>Serial</span><b>${esc(e.serial_number||'—')}</b></div></div><form id="assetStatus"><div class="field"><label>Completion status</label><select name="status">${['not_started','qa','commissioning','witness','blocked','complete'].map(x=>`<option value="${x}" ${x===e.status?'selected':''}>${x.replaceAll('_',' ')}</option>`).join('')}</select></div><button class="btn btn-primary">Update asset</button></form></div><div class="card"><div class="section-head"><h3>Recent evidence</h3><button class="btn btn-small" id="assetEvidence">+ Photo</button></div>${(d.files||[]).slice(0,8).map(f=>`<a class="file-row" target="_blank" href="/api/files/${f.id}"><b>${esc(f.file_name)}</b><span>${fmtTime(f.created_at)}</span></a>`).join('')||'<div class="empty">No asset evidence yet.</div>'}</div></div><div class="section-head"><h3>Commissioning history</h3><span>Asset-linked records</span></div>${(d.inspections||[]).length?`<div class="table-wrap"><table><thead><tr><th>Test</th><th>Template</th><th>Status</th><th>Updated</th></tr></thead><tbody>${d.inspections.map(i=>`<tr data-inspection="${i.id}" style="cursor:pointer"><td><strong>${esc(i.title)}</strong></td><td>${esc(i.template_name||'')}</td><td>${pill(i.status)}</td><td>${fmtTime(i.updated_at)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="card empty">No asset tests yet.</div>'}`,true);$('#copyAssetLink').onclick=()=>{navigator.clipboard?.writeText(`${location.origin}/?asset=${eid}`);toast('Asset QR link copied')};$('#assetStatus').onsubmit=async ev=>{ev.preventDefault();await api(`/api/equipment/${eid}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(ev.target)))});toast('Asset status updated');$('#modal').remove();await loadAll();render()};$('#assetEvidence').onclick=()=>{const m=$('#modal');m.remove();openEvidenceUpload()};$$('[data-inspection]').forEach(r=>r.onclick=()=>openInspection(r.dataset.inspection))}catch(err){toast(err.message)}}

async function openScanner(){if(!('BarcodeDetector'in window)){modal('Scan asset',`<div class="banner"><div>▣</div><div><strong>Camera QR scanning is not supported in this browser.</strong><p>Use the manual tag search below, or open Qx in a current Chromium/Android browser.</p></div></div><div class="field"><label>Asset tag</label><input id="manualAsset" placeholder="AHU-01"></div><button class="btn btn-primary" id="findAsset">Find asset</button>`);$('#findAsset').onclick=()=>{const tag=$('#manualAsset').value.trim().toLowerCase(),e=state.equipment.find(x=>String(x.tag).toLowerCase()===tag);if(!e)return toast('Asset tag not found');$('#modal').remove();openAssetPassport(e.id)};return}modal('Scan asset QR',`<video id="scanVideo" autoplay playsinline style="width:100%;border-radius:14px;background:#000;min-height:300px"></video><p class="muted">Point the camera at a Qx asset QR code.</p>`,true);try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}}),video=$('#scanVideo');video.srcObject=stream;const detector=new BarcodeDetector({formats:['qr_code']});const tick=async()=>{if(!document.body.contains(video)){stream.getTracks().forEach(t=>t.stop());return}try{const codes=await detector.detect(video);if(codes[0]){const raw=codes[0].rawValue||'',u=new URL(raw,location.origin),eid=u.searchParams.get('asset');if(eid){stream.getTracks().forEach(t=>t.stop());$('#modal').remove();openAssetPassport(eid);return}}}catch{}requestAnimationFrame(tick)};tick()}catch(e){toast('Camera access unavailable')};}

async function runBuilder(){if(!state.projectId)return toast('Select a project first');const text=$('#builderText')?.value.trim();if(!text)return toast('Paste project text first');const box=$('#builderResult');box.innerHTML='<div class="empty">Analysing project text…</div>';try{const r=await api('/api/ai/project-builder',{method:'POST',body:JSON.stringify({project_id:state.projectId,source_text:text})});const eq=r.proposal?.equipment||[];box.innerHTML=`<div class="eyebrow">REVIEW PROPOSAL</div><h3>${eq.length} equipment tags identified</h3><p class="muted">${esc(r.proposal?.notes||'')}</p><div class="tag-cloud">${eq.slice(0,120).map(e=>`<span>${esc(e.tag)}</span>`).join('')}</div><button class="btn btn-primary" id="applyBuilder" ${eq.length?'':'disabled'}>Apply ${eq.length} assets to project</button>`;$('#applyBuilder')?.addEventListener('click',async()=>{const a=await api('/api/ai/project-builder/apply',{method:'POST',body:JSON.stringify({job_id:r.id})});await loadAll();toast(`${a.created} assets created • ${a.skipped} skipped`);state.view='equipment';render()})}catch(e){box.innerHTML=`<div class="error">${esc(e.message)}</div>`}}

function exportEquipmentCsv(){const rows=[['tag','name','system','subsystem','building','level','area','equipment_type','manufacturer','model','serial_number','status'],...state.equipment.map(e=>[e.tag,e.name,e.system,e.subsystem,e.building,e.level,e.area,e.equipment_type,e.manufacturer,e.model,e.serial_number,e.status])];const q=v=>`"${String(v??'').replaceAll('"','""')}"`,csv=rows.map(r=>r.map(q).join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`${currentProject()?.code||'qx'}-equipment.csv`;a.click();URL.revokeObjectURL(a.href)}

function openUserForm(){modal('Add Qx user',`<form id="userForm"><div class="formgrid"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Role</label><select name="role"><option value="technician">Technician</option><option value="engineer">Engineer</option><option value="pm">Project Manager</option><option value="admin">Administrator</option></select></div><div class="field"><label>Temporary password</label><input name="password" type="password" minlength="12" required></div></div><button class="btn btn-primary">Create user</button></form>`);formSubmit($('#userForm'),'/api/users','User created')}

async function openInspection(iid){try{const d=await api(`/api/inspections/${iid}`);const i=d.inspection;modal(i.title,`<div class="banner"><div>✓</div><div><strong>${esc(i.template_name)}</strong><p>${esc(i.equipment_tag||'Project/system test')} • ${esc(i.discipline)} • ${esc(i.stage)}</p></div></div><div id="results">${d.results.map(r=>`<div class="result-row"><div class="meta"><span>${esc(r.section)}</span>${r.hold_point?'<span class="pill witness_required">HOLD POINT</span>':''}</div><h4>${esc(r.item_text)}</h4><div class="result-buttons" data-result-id="${r.id}"><button class="btn btn-small ${r.result==='pass'?'selected pass':''}" data-value="pass">PASS</button><button class="btn btn-small ${r.result==='fail'?'selected fail':''}" data-value="fail">FAIL</button><button class="btn btn-small ${r.result==='na'?'selected na':''}" data-value="na">N/A</button></div></div>`).join('')}</div>`,true);$$('[data-result-id] button').forEach(b=>b.onclick=async()=>{const row=b.closest('[data-result-id]');try{const r=await api(`/api/inspection-results/${row.dataset.resultId}`,{method:'PATCH',body:JSON.stringify({result:b.dataset.value})});row.querySelectorAll('button').forEach(x=>x.className='btn btn-small');b.classList.add('selected',b.dataset.value);toast(b.dataset.value==='fail'?'Failed check — Category A punch auto-created':`Result saved • ${r.status.replaceAll('_',' ')}`);await loadAll()}catch(err){toast(err.message)}})}catch(err){toast(err.message)}}

async function openPoint(pid){const p=state.points.find(x=>x.id===pid);if(!p)return;modal(`I/O Checkout — ${p.point_name}`,`<div class="banner"><div>↯</div><div><strong>${esc(p.controller||'Controller')} • ${esc(p.point_type)}</strong><p>${esc([p.io_address,p.cable_number,p.terminal].filter(Boolean).join(' • ')||'Field point')}</p></div></div><form id="pf"><div class="formgrid"><div class="field"><label>Field device</label><select name="field_status">${statusOpts(p.field_status)}</select></div><div class="field"><label>Controller I/O</label><select name="controller_status">${statusOpts(p.controller_status)}</select></div><div class="field"><label>Graphics / HMI</label><select name="graphics_status">${statusOpts(p.graphics_status)}</select></div><div class="field"><label>Alarm / sequence</label><select name="alarm_status">${statusOpts(p.alarm_status)}</select></div><div class="field span2"><label>Comment</label><textarea name="comment">${esc(p.comment||'')}</textarea></div></div><button class="btn btn-primary">Save point test</button></form>`);$('#pf').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{await api(`/api/bms-points/${pid}`,{method:'PATCH',body:JSON.stringify(data)});$('#modal').remove();await loadAll();render();toast('I/O point updated')}catch(err){toast(err.message)}}}
function statusOpts(v){return ['not_tested','pass','fail','na'].map(x=>`<option value="${x}" ${x===v?'selected':''}>${x.replaceAll('_',' ')}</option>`).join('')}

function openPointImport(){if(!currentProject()&&!state.projectId)return toast('Select a project before importing points');modal('Import BMS I/O points from CSV',`<div class="banner"><div>⇧</div><div><strong>Fast point-list ingestion</strong><p>Paste CSV exported from Excel/Simpro/design schedules. Required columns: point_name, point_type. Optional: controller, io_address, cable_number, terminal, field_device, engineering_units, normal_state.</p></div></div><div class="field"><label>CSV data</label><textarea id="csv" style="min-height:260px" placeholder="controller,point_name,point_type,io_address,cable_number,terminal\nJACE-01,AHU-01 Supply Air Temp,AI,UI1,BMS-001,X1:1\nJACE-01,AHU-01 Fan Enable,DO,UO1,BMS-002,X1:2"></textarea></div><button class="btn btn-primary" id="doImport">Import points</button>`,true);$('#doImport').onclick=async()=>{try{const rows=parseCSV($('#csv').value);if(!rows.length)throw new Error('No valid CSV rows found');const r=await api('/api/bms-points/import',{method:'POST',body:JSON.stringify({project_id:state.projectId,points:rows})});$('#modal').remove();await loadAll();render();toast(`${r.created} points imported`)}catch(err){toast(err.message)}}}
function parseCSV(text){const lines=text.trim().split(/\r?\n/).filter(Boolean);if(lines.length<2)return[];const split=line=>{const out=[];let cur='',q=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(q&&line[i+1]==='"'){cur+='"';i++}else q=!q}else if(c===','&&!q){out.push(cur.trim());cur=''}else cur+=c}out.push(cur.trim());return out};const headers=split(lines[0]).map(x=>x.toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,''));return lines.slice(1).map(line=>{const vals=split(line),o={};headers.forEach((h,i)=>o[h]=vals[i]||'');return o}).filter(x=>x.point_name&&x.point_type)}

async function openDefect(did){const d=state.defects.find(x=>x.id===did);if(!d)return;modal(`Punch ${d.category} — ${d.title}`,`<div class="banner"><div>!</div><div><strong>${esc(d.equipment_tag||'Project / system')}</strong><p>${esc(d.description||'No description')}</p></div></div><div class="formgrid"><div class="card"><div class="eyebrow">Status</div><div style="margin-top:8px">${pill(d.status)}</div></div><div class="card"><div class="eyebrow">Owner</div><div style="margin-top:8px">${esc(d.assigned_name||'Unassigned')}</div></div></div><form id="df" style="margin-top:12px"><div class="field"><label>Update status</label><select name="status"><option value="open">Open</option><option value="assigned">Assigned</option><option value="rectified">Rectified — ready to verify</option><option value="verified">Verified</option><option value="closed">Closed</option></select></div><div class="field"><label>Rectification / verification note</label><textarea name="rectification_note">${esc(d.rectification_note||'')}</textarea></div><button class="btn btn-primary">Update punch item</button></form>`);$('#df').onsubmit=async e=>{e.preventDefault();try{await api(`/api/defects/${did}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});$('#modal').remove();await loadAll();render();toast('Punch item updated')}catch(err){toast(err.message)}}}

async function openTurnover(tid){try{const d=await api(`/api/turnover/${tid}`);modal(d.package.name,`<div class="banner"><div>▣</div><div><strong>${Number(d.package.readiness_percent||0)}% ready for handover</strong><p>${esc(d.package.system_code||'Project-wide')} • ${d.package.complete_items||0}/${d.package.required_items||0} required items complete</p></div></div><div class="table-wrap"><table><thead><tr><th>Category</th><th>Required evidence / gate</th><th>Status</th></tr></thead><tbody>${d.items.map(x=>`<tr><td>${esc(x.category)}</td><td><strong>${esc(x.name)}</strong>${x.note?`<br><span class="muted">${esc(x.note)}</span>`:''}</td><td><select class="mini-select" data-toi="${x.id}"><option value="missing" ${x.status==='missing'?'selected':''}>Missing</option><option value="in_progress" ${x.status==='in_progress'?'selected':''}>In progress</option><option value="complete" ${x.status==='complete'?'selected':''}>Complete</option><option value="accepted" ${x.status==='accepted'?'selected':''}>Accepted</option></select></td></tr>`).join('')}</tbody></table></div>`,true);$$('[data-toi]').forEach(s=>s.onchange=async()=>{try{await api(`/api/turnover-items/${s.dataset.toi}`,{method:'PATCH',body:JSON.stringify({status:s.value})});toast('Turnover gate updated');await loadAll()}catch(err){toast(err.message)}})}catch(err){toast(err.message)}}


document.addEventListener('click',async e=>{const b=e.target.closest('[data-route]');if(b){state.view=b.dataset.route;render();return}if(e.target.id==='openDossier'||e.target.id==='openDossier2'){window.open(`/api/handover/dossier?project_id=${encodeURIComponent(state.projectId)}`,'_blank');return}if(e.target.id==='projectSignoff'){openSignature();return}if(e.target.id==='addDocument'){openDocumentForm();return}if(e.target.id==='refreshCopilot'){await loadCloseout();render();return}if(e.target.id==='createShare'){try{const r=await api('/api/client-share',{method:'POST',body:JSON.stringify({project_id:state.projectId,label:'Client live status',expires_days:30})});await navigator.clipboard?.writeText(r.url);modal('Client live status link',`<div class="banner"><div>↗</div><div><strong>Read-only client link created</strong><p>Expires ${fmtDate(r.expires_at)}. The link has also been copied to your clipboard.</p></div></div><div class="field"><input value="${esc(r.url)}" readonly></div><a class="btn btn-primary" href="${esc(r.url)}" target="_blank">Open client view</a>`)}catch(err){toast(err.message)}}});
const _renderV6=render;render=function(){_renderV6();if(state.view==='closeout'&&!state.copilot){loadCloseout().then(()=>{if(state.view==='closeout'){const c=state.copilot;_renderV6()}}).catch(()=>{})}};

window.addEventListener('online',()=>{updateQueueBadge();toast('Connection restored — synchronising queued field updates');flushQueue()});window.addEventListener('offline',()=>{updateQueueBadge();toast('Offline field mode — updates will queue and sync automatically')});

const _loadAllV7=loadAll;loadAll=async function(){await _loadAllV7();await loadV7()};
document.addEventListener('click',async e=>{if(e.target.id==='addDrawing')return openDrawingForm();if(e.target.id==='refreshAlerts'){await api('/api/notifications/scan',{method:'POST',body:JSON.stringify({project_id:state.projectId||null})});await loadV7();render();toast('Risk scan complete');return}const r=e.target.closest('[data-drawing]');if(r)return openDrawing(r.dataset.drawing)});


const _loadAllV8=loadAll;loadAll=async function(){await _loadAllV8();await loadV8()};
document.addEventListener('click',async e=>{const tc=e.target.closest('[data-template]');if(tc){openTemplate(tc.dataset.template);return}if(e.target.id==='newTemplate'){openTemplateForm();return}const p=e.target.closest('[data-open-project]');if(p){state.projectId=p.dataset.openProject;state.view='dashboard';await loadAll();render();return}if(e.target.id==='downloadPack')return downloadOfflinePack();if(e.target.id==='addObservation')return openObservationForm();if(e.target.id==='addMilestone')return openMilestoneForm();if(e.target.id==='applySmart'){try{const r=await api('/api/ai/form-builder/apply',{method:'POST',body:JSON.stringify({job_id:e.target.dataset.job})});state.smartForm=null;await loadAll();state.view='templates';render();toast(`Template created • ${r.item_count} checks`)}catch(err){toast(err.message)}}});
document.addEventListener('submit',async e=>{if(e.target.id==='smartForm'){e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));d.project_id=state.projectId;const r=await api('/api/ai/form-builder',{method:'POST',body:JSON.stringify(d)});state.smartForm=r;render()}catch(err){toast(err.message)}}});
boot();
setTimeout(()=>flushQueue(),1200);
